CREATE TABLE credit_ledger (id UUID PRIMARY KEY,hotel_id UUID NOT NULL,branch_id UUID NOT NULL,customer_id UUID NOT NULL,entry_date TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,kind VARCHAR(20) NOT NULL CHECK(kind IN ('CHARGE','PAYMENT','ADJUSTMENT')),amount NUMERIC(19,4) NOT NULL CHECK(amount<>0),source_id UUID NOT NULL,description VARCHAR(1000) NOT NULL,actor_id UUID NOT NULL REFERENCES users(id),UNIQUE(hotel_id,branch_id,customer_id,kind,source_id),FOREIGN KEY(customer_id,hotel_id) REFERENCES customers(id,hotel_id),FOREIGN KEY(branch_id,hotel_id) REFERENCES branches(id,hotel_id));
CREATE INDEX idx_credit_ledger_customer ON credit_ledger(hotel_id,branch_id,customer_id,entry_date);
